namespace {

// direction of the bump generated by bumpy_sphere()
const Point bump_dir(0.0, 0.0, 1.0);

// brute-force distance from a point to the triangle soup of a mesh
Scalar distance_to_mesh(const SurfaceMesh& mesh, const Point& p)
{
    Scalar d = std::numeric_limits<Scalar>::max();
    Point nearest;
    for (auto f : mesh.faces())
    {
        auto fv = mesh.vertices(f);
        const Point& p0 = mesh.position(*fv);
        ++fv;
        const Point& p1 = mesh.position(*fv);
        ++fv;
        const Point& p2 = mesh.position(*fv);
        d = std::min(d, dist_point_triangle(p, p0, p1, p2, nearest));
    }
    return d;
}

// maximum distance of the vertices of mesh to the surface of reference
Scalar max_vertex_distance_to_mesh(const SurfaceMesh& mesh,
                                   const SurfaceMesh& reference)
{
    Scalar dmax = 0.0;
    for (auto v : mesh.vertices())
        dmax = std::max(dmax, distance_to_mesh(reference, mesh.position(v)));
    return dmax;
}

using Segments = std::vector<std::pair<Point, Point>>;

Segments boundary_segments(const SurfaceMesh& mesh)
{
    Segments segments;
    for (auto e : mesh.edges())
        if (mesh.is_boundary(e))
            segments.emplace_back(mesh.position(mesh.vertex(e, 0)),
                                  mesh.position(mesh.vertex(e, 1)));
    return segments;
}

Scalar distance_to_segments(const Segments& segments, const Point& p)
{
    Scalar d = std::numeric_limits<Scalar>::max();
    Point nearest;
    for (const auto& s : segments)
        d = std::min(d,
                     dist_point_line_segment(p, s.first, s.second, nearest));
    return d;
}

// angular distance of a position to the bump direction, in radians
Scalar angle_to_bump(const Point& p)
{
    const Scalar cosine =
        std::clamp<Scalar>(dot(normalize(p), bump_dir), -1.0, 1.0);
    return std::acos(cosine);
}

// mean length of edges touched by vertices in the bump region (angular
// distance < 0.4) and in the far region (angular distance > 1.2)
std::pair<Scalar, Scalar> bump_vs_far_mean_edge_length(const SurfaceMesh& mesh)
{
    Scalar bump_sum = 0.0, far_sum = 0.0;
    size_t bump_count = 0, far_count = 0;
    for (auto v : mesh.vertices())
    {
        const Scalar angle = angle_to_bump(mesh.position(v));
        Scalar sum = 0.0;
        size_t count = 0;
        for (auto h : mesh.halfedges(v))
        {
            sum += distance(mesh.position(v),
                            mesh.position(mesh.to_vertex(h)));
            ++count;
        }
        if (angle < 0.4)
        {
            bump_sum += sum / count;
            ++bump_count;
        }
        else if (angle > 1.2)
        {
            far_sum += sum / count;
            ++far_count;
        }
    }
    EXPECT_GT(bump_count, 0u);
    EXPECT_GT(far_count, 0u);
    return {bump_sum / bump_count, far_sum / far_count};
}

// check validity of the triangle topology and absence of degenerate geometry
void expect_valid_triangle_mesh(const SurfaceMesh& mesh)
{
    EXPECT_TRUE(mesh.is_triangle_mesh());
    for (auto v : mesh.vertices())
    {
        EXPECT_TRUE(mesh.is_manifold(v));
        const Point& p = mesh.position(v);
        EXPECT_FALSE(std::isnan(p[0]) || std::isnan(p[1]) || std::isnan(p[2]));
    }
    for (auto f : mesh.faces())
    {
        auto fv = mesh.vertices(f);
        const Point& p0 = mesh.position(*fv);
        ++fv;
        const Point& p1 = mesh.position(*fv);
        ++fv;
        const Point& p2 = mesh.position(*fv);
        EXPECT_GT(norm(cross(p1 - p0, p2 - p0)), 0.0);
    }
}

} // namespace

// adaptive remeshing
TEST(RemeshingTest, adaptive_remeshing_with_features)
{
    auto mesh = cylinder();
    triangulate(mesh);
    detect_features(mesh, 25);
    auto bb = bounds(mesh).size();
    adaptive_remeshing(mesh, 0.001 * bb, // min length
                       1.0 * bb,         // max length
                       0.001 * bb);      // approx. error
    EXPECT_EQ(mesh.n_vertices(), 6u);
}

TEST(RemeshingTest, adaptive_remeshing_with_boundary)
{
    // mesh with boundary
    auto mesh = open_cone();
    auto bb = bounds(mesh).size();
    adaptive_remeshing(mesh, 0.01 * bb, // min length
                       1.0 * bb,        // max length
                       0.01 * bb);      // approx. error
    EXPECT_EQ(mesh.n_vertices(), size_t(104));
}

TEST(RemeshingTest, adaptive_remeshing_with_selection)
{
    auto mesh = icosphere(1);

    // select half the vertices
    auto selected = mesh.add_vertex_property<bool>("v:selected");
    for (auto v : mesh.vertices())
        if (mesh.position(v)[1] > 0)
            selected[v] = true;

    auto bb = bounds(mesh).size();
    adaptive_remeshing(mesh, 0.01 * bb, // min length
                       1.0 * bb,        // max length
                       0.01 * bb);      // approx. error
    EXPECT_EQ(mesh.n_vertices(), size_t(62));
}

TEST(RemeshingTest, uniform_remeshing)
{
    auto mesh = open_cone();
    uniform_remeshing(mesh, 0.5);
    EXPECT_EQ(mesh.n_vertices(), size_t(41));
}

// After topological edits and back-projection in a region of strongly
// varying curvature, the mesh must remain a valid triangle mesh, stay on
// the reference surface, and adapt its local edge length to curvature.
TEST(RemeshingTest, adaptive_remeshing_curvature_sizing_with_projection)
{
    auto mesh = bumpy_sphere();
    SurfaceMesh reference;
    reference.assign(mesh);

    const Scalar bb = bounds(mesh).size();
    const Scalar min_length = 0.02 * bb;
    const Scalar max_length = 0.5 * bb;
    const Scalar approx_error = 0.005 * bb;

    adaptive_remeshing(mesh, min_length, max_length, approx_error,
                       10,   // iterations
                       true  // use projection
    );

    // valid triangle topology, no degenerate faces
    expect_valid_triangle_mesh(mesh);

    // geometric criterion with projection on: every vertex of the closed
    // mesh is projected onto the reference surface, so the distance of the
    // vertices to the input surface must be (numerically) zero
    EXPECT_LT(max_vertex_distance_to_mesh(mesh, reference), 1e-4 * bb);

    // curvature-adaptive sizing: the high-curvature bump region must be
    // meshed with clearly shorter edges than the spherical far region
    // (a uniform, curvature-agnostic sizing would give a ratio close to 1)
    const auto [bump_mean, far_mean] = bump_vs_far_mean_edge_length(mesh);
    EXPECT_LT(bump_mean, 0.8 * far_mean);

    // edge lengths respect the target band of the algorithm (4/5 and 4/3
    // thresholds around the clamped sizing field), with slack for the
    // approximate convergence of incremental remeshing
    for (auto e : mesh.edges())
    {
        const Scalar length = distance(mesh.position(mesh.vertex(e, 0)),
                                       mesh.position(mesh.vertex(e, 1)));
        EXPECT_LT(length, 1.5 * 4.0 / 3.0 * max_length);
        EXPECT_GT(length, 0.25 * min_length);
    }
}

// The local edge length must react to the approximation-error parameter in
// an explainable way: halving the tolerable error refines the curved
// region (target length h ~ sqrt(6 * e * r)), while the flat region stays
// coarse.
TEST(RemeshingTest, adaptive_remeshing_approx_error_controls_sizing)
{
    const auto input = bumpy_sphere();
    const Scalar bb = bounds(input).size();

    auto coarse = input;
    auto fine = input;
    adaptive_remeshing(coarse, 0.02 * bb, 0.5 * bb, 0.01 * bb);
    adaptive_remeshing(fine, 0.02 * bb, 0.5 * bb, 0.0025 * bb);

    expect_valid_triangle_mesh(coarse);
    expect_valid_triangle_mesh(fine);

    // smaller approximation error -> more vertices overall
    EXPECT_GT(fine.n_vertices(), coarse.n_vertices());

    // the refinement concentrates on the high-curvature bump region:
    // quartering the error roughly halves the target edge length there
    // (h ~ sqrt(6 * e * r)), which is the explainable parameter relation
    const auto [bump_coarse, far_coarse] = bump_vs_far_mean_edge_length(coarse);
    const auto [bump_fine, far_fine] = bump_vs_far_mean_edge_length(fine);
    EXPECT_LT(bump_fine, 0.65 * bump_coarse);
    EXPECT_LT(far_fine, far_coarse);
    EXPECT_LT(bump_fine, far_fine);
}

// Boundary vertices must stay on the input boundary curve: the algorithm
// may split and collapse boundary edges, but it must not pull the boundary
// into the interior to satisfy the sizing target.
TEST(RemeshingTest, adaptive_remeshing_preserves_boundary_curve)
{
    auto mesh = open_cone();
    const auto boundary = boundary_segments(mesh);
    SurfaceMesh reference;
    reference.assign(mesh);

    const Scalar bb = bounds(mesh).size();
    adaptive_remeshing(mesh, 0.01 * bb, 1.0 * bb, 0.01 * bb, 10, true);

    expect_valid_triangle_mesh(mesh);

    // the boundary remains a closed loop on the input boundary polyline
    size_t n_boundary = 0;
    for (auto v : mesh.vertices())
    {
        if (!mesh.is_boundary(v))
            continue;
        ++n_boundary;
        EXPECT_LT(distance_to_segments(boundary, mesh.position(v)), 1e-5);
        int n_boundary_neighbors = 0;
        for (auto h : mesh.halfedges(v))
            if (mesh.is_boundary(mesh.edge(h)))
                ++n_boundary_neighbors;
        EXPECT_EQ(n_boundary_neighbors, 2);
    }
    EXPECT_GE(n_boundary, 3u);

    // interior vertices are projected onto the reference surface
    for (auto v : mesh.vertices())
        if (!mesh.is_boundary(v))
            EXPECT_LT(distance_to_mesh(reference, mesh.position(v)),
                      1e-4 * bb);
}

// Feature edges must survive remeshing as sharp polylines tracing the
// original feature curves, instead of being smoothed away for the sake of
// uniform edge lengths.
TEST(RemeshingTest, adaptive_remeshing_preserves_feature_edges)
{
    auto mesh = cylinder();
    triangulate(mesh);
    detect_features(mesh, 25);
    SurfaceMesh reference;
    reference.assign(mesh);

    const Scalar bb = bounds(mesh).size();
    adaptive_remeshing(mesh, 0.02 * bb, 0.1 * bb, 0.005 * bb, 10, true);

    expect_valid_triangle_mesh(mesh);

    // closed mesh with projection: all vertices on the reference surface
    EXPECT_LT(max_vertex_distance_to_mesh(mesh, reference), 1e-4 * bb);

    auto efeature = mesh.get_edge_property<bool>("e:feature");
    auto vfeature = mesh.get_vertex_property<bool>("v:feature");
    ASSERT_TRUE(efeature);
    ASSERT_TRUE(vfeature);

    // feature edges still exist after remeshing
    size_t n_feature_edges = 0;
    for (auto e : mesh.edges())
        if (efeature[e])
            ++n_feature_edges;
    EXPECT_GT(n_feature_edges, 0u);

    const Scalar cos_60 = 0.5;
    for (auto v : mesh.vertices())
    {
        if (!vfeature[v])
            continue;

        // feature vertices still trace the analytic feature curves of the
        // cylinder: the rim circles of radius 1 in the planes z = 0 and
        // z = height
        const Point& p = mesh.position(v);
        const Scalar radial = std::abs(std::sqrt(p[0] * p[0] + p[1] * p[1]) -
                                       Scalar(1.0));
        const Scalar axial =
            std::min<Scalar>(std::abs(p[2]), std::abs(p[2] - Scalar(2.5)));
        EXPECT_LT(std::sqrt(radial * radial + axial * axial), 0.02 * bb);

        // the cylinder rims are closed loops: exactly two feature neighbors
        int n_feature_neighbors = 0;
        for (auto h : mesh.halfedges(v))
            if (efeature[mesh.edge(h)])
                ++n_feature_neighbors;
        EXPECT_EQ(n_feature_neighbors, 2);
    }

    // feature edges remain sharp: the dihedral angle across them stays
    // well above the detection threshold of 25 degrees
    for (auto e : mesh.edges())
    {
        if (efeature[e] && !mesh.is_boundary(e))
        {
            const Normal n0 =
                face_normal(mesh, mesh.face(mesh.halfedge(e, 0)));
            const Normal n1 =
                face_normal(mesh, mesh.face(mesh.halfedge(e, 1)));
            EXPECT_LT(dot(n0, n1), cos_60);
        }
    }
}

// Feature corners (more than two incident feature edges) are locked: when
// the sizing target conflicts with the protected geometry, the target may
// legitimately be missed, but the corners must not move.
TEST(RemeshingTest, adaptive_remeshing_locked_feature_corners)
{
    auto mesh = hexahedron();
    triangulate(mesh);
    detect_features(mesh, 25);

    auto efeature = mesh.get_edge_property<bool>("e:feature");
    auto vfeature = mesh.get_vertex_property<bool>("v:feature");

    // collect the corners: feature vertices with != 2 feature neighbors
    std::vector<Point> corners;
    for (auto v : mesh.vertices())
    {
        if (!vfeature[v])
            continue;
        int n_feature_neighbors = 0;
        for (auto h : mesh.halfedges(v))
            if (efeature[mesh.edge(h)])
                ++n_feature_neighbors;
        if (n_feature_neighbors != 2)
            corners.push_back(mesh.position(v));
    }
    ASSERT_EQ(corners.size(), 8u);

    const Scalar bb = bounds(mesh).size();

    // aggressive sizing: the minimum target length is on the order of the
    // cube edge length, so the sizing field conflicts with the locked
    // corners and the short feature edges around them
    adaptive_remeshing(mesh, 0.3 * bb, 1.0 * bb, 0.1 * bb, 10, true);

    expect_valid_triangle_mesh(mesh);

    // every protected corner is still present at its exact position;
    // moving a locked corner to satisfy the edge-length target would be
    // caught here
    for (const auto& corner : corners)
    {
        Scalar dmin = std::numeric_limits<Scalar>::max();
        Vertex closest;
        for (auto v : mesh.vertices())
        {
            const Scalar d = distance(mesh.position(v), corner);
            if (d < dmin)
            {
                dmin = d;
                closest = v;
            }
        }
        EXPECT_LT(dmin, 1e-6) << "protected feature corner moved";
        EXPECT_TRUE(vfeature[closest]);

        // it is still a corner, i.e. not a regular feature vertex
        int n_feature_neighbors = 0;
        for (auto h : mesh.halfedges(closest))
            if (efeature[mesh.edge(h)])
                ++n_feature_neighbors;
        EXPECT_NE(n_feature_neighbors, 2);
    }

    // NOTE: deliberately no assertion on a global minimum edge length.
    // Edges incident to locked corners may legitimately stay shorter than
    // the target because the conflict is resolved in favor of the
    // protected geometry.
}

// Without back-projection the on-surface criterion does not apply; the
// applicable criterion is a chord-error-scale envelope around the input
// surface plus preservation of the macroscopic shape.
TEST(RemeshingTest, adaptive_remeshing_without_projection)
{
    auto mesh = bumpy_sphere();
    SurfaceMesh reference;
    reference.assign(mesh);

    const Scalar bb = bounds(mesh).size();
    const Scalar max_length = 0.5 * bb;

    adaptive_remeshing(mesh, 0.02 * bb, max_length, 0.005 * bb,
                       10,    // iterations
                       false  // no projection
    );

    expect_valid_triangle_mesh(mesh);

    // loose envelope: tangential smoothing and midpoint splits keep the
    // surface within a fraction of the target edge length of the input
    const Scalar dmax = max_vertex_distance_to_mesh(mesh, reference);
    EXPECT_LT(dmax, 0.1 * max_length);

    // the bump (macroscopic shape) is preserved: peak radius stays well
    // above the unit sphere
    Scalar max_radius = 0.0;
    for (auto v : mesh.vertices())
        max_radius = std::max(max_radius, norm(mesh.position(v)));
    EXPECT_GT(max_radius, 1.2);

    // curvature-adaptive sizing also holds without projection
    const auto [bump_mean, far_mean] = bump_vs_far_mean_edge_length(mesh);
    EXPECT_LT(bump_mean, 0.8 * far_mean);
}

// The two projection modes use different surface-fitting criteria:
// projection pins vertices to the reference surface, while tangential
// smoothing without projection leaves a measurable chord-error-scale gap.
TEST(RemeshingTest, adaptive_remeshing_projection_on_off_criteria)
{
    const auto input = bumpy_sphere();
    const Scalar bb = bounds(input).size();

    SurfaceMesh reference;
    reference.assign(input);

    auto projected = input;
    auto unprojected = input;
    adaptive_remeshing(projected, 0.02 * bb, 0.5 * bb, 0.005 * bb, 10, true);
    adaptive_remeshing(unprojected, 0.02 * bb, 0.5 * bb, 0.005 * bb, 10,
                       false);

    expect_valid_triangle_mesh(projected);
    expect_valid_triangle_mesh(unprojected);

    // with projection the vertices lie on the reference surface
    const Scalar dmax_on = max_vertex_distance_to_mesh(projected, reference);
    EXPECT_LT(dmax_on, 1e-4 * bb);

    // without projection they only stay within the loose envelope ...
    const Scalar dmax_off =
        max_vertex_distance_to_mesh(unprojected, reference);
    EXPECT_LT(dmax_off, 0.05 * bb);

    // ... and the two modes are genuinely different: the unprojected
    // surface deviates measurably from the reference instead of being
    // pinned to it
    EXPECT_GT(dmax_off, 1e-3 * bb);
}
